# Function to get the valid movements (cardinal directions)
def get_valid_movements(x, y):
    movements = []
    if x > 0:
        movements.append((x-1, y))  # Up
    if x < len(grid) - 1:
        movements.append((x+1, y))  # Down
    if y > 0:
        movements.append((x, y-1))  # Left
    if y < len(grid[0]) - 1:
        movements.append((x, y+1))  # Right
    return movements

# Function to perform DFS traversal and group adjacent states
def dfs_traversal(x, y, visited):
    visited.add((x, y))

    for dx, dy in get_valid_movements(x, y):
        if (dx, dy) not in visited:
            dfs_traversal(dx, dy, visited)

# Function to perform state abstraction and group adjacent states
