# define the valid movements in cardinal directions (up, down, left, right)
movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

def state_abstraction(grid):
    # Initialize a dictionary to store visited states and their corresponding abstract states
    visited_states = {}

    # Define a helper function to perform DFS from a given state
    def dfs(state):
        # If the state is already visited, return its corresponding abstract state
        if state in visited_states:
            return visited_states[state]

        # Initialize a set to store all adjacent states
        adjacent_states = set()

        # Iterate over all valid movements
        for movement in movements:
            new_state = (state[0] + movement[0], state[1] + movement[1])

            # Check if the new state is within grid boundaries and contains the goal
            if 0 <= new_state[0] < len(grid) and 0 <= new_state[1] < len(grid[0]) and (new_state == (len(grid)-1, len(grid[0])-1)):
                return visited_states.setdefault(state, new_state)

            # If the new state is not within grid boundaries or does not contain the goal, check its position in the grid
            elif 0 <= new_state[0] < len(grid) and 0 <= new_state[1] < len(grid[0]) and grid[new_state[0]][new_state[1]] != None:
                adjacent_states.add(new_state)

        # If no adjacent states are found, return the current state
        if not adjacent_states:
            return visited_states.setdefault(state, state)

        # Otherwise, perform DFS from each adjacent state to find their abstract states
        else:
            for new_state in adjacent_states:
                dfs(new_state)

    # Initialize a dictionary to store all abstract states and their corresponding IDs
    abstract_states = {}

    # Perform DFS from the start state (0, 0) to find its abstract state
    abstract_states[dfs((0, 0))] = len(abstract_states)

    # Iterate over all cells in the grid
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            # If a cell does not contain the goal and is within grid boundaries, perform DFS to find its abstract state
            if (i,j) != (len(grid)-1,len(grid[0])-1) and 0 <= i < len(grid) and 0 <= j < len(grid[0]) and grid[i][j] != None:
                abstract_states[dfs((i, j))] = len(abstract_states)

    return list(abstract_states.values())

